            }
            for (String grade : GRADES) {
                if (!request.gradeGrace().containsKey(grade)) {
                    continue;
                }
                String days = request.gradeGrace().get(grade) == null ? "" : request.gradeGrace().get(grade).trim();
                if (!days.isEmpty() && !days.matches("\\d{1,4}")) {
