package net.officefloor.hq.app.setting;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.Map;

/** A sheet's settings in force on its today: the clerk limit (two decimals; null: no limit) the floor (two
 *  decimals) and the terms (days; a claim's due-by is its date plus them) and the late percent (two decimals) and the
 *  policy date (null: the sheet's today; a claim dated before it rounds half up, on or after it half to even) and the
 *  period numbering from (null: off; on or after it, by the sheet's today, a claim opened is numbered within its
 *  period) and the grades' own terms (days, by grade; a grade without its own uses the sheet's terms) and the cap
 *  (two decimals; null: none; a person's due-total is at most it) and the proof threshold (two decimals; null: none) and the note threshold (two decimals; null: none); and every value of the dated ones; and the permission matrix (not dated); and the grace days (null: off; not dated); and the entry date (null: off; not dated; a new claim given no date is dated it); and the grades' grace (days, by grade; a grade without one has none); and the grades' own proof thresholds (two decimals, by grade; a grade without one uses the sheet's); and the pot (two decimals; null: none; not dated); and the parent sheet (a sheet id; null: none; not dated); and the fiscal year start month (1 to 12; not dated); and the alert threshold (two decimals; null: off; not dated); and the rounding mode (half-up or half-even; null: none). */
public record Settings(String sheetId, BigDecimal clerkLimit, BigDecimal floor, int terms, BigDecimal latePct,
        LocalDate policyDate, LocalDate periodNumberingFrom, Map<String, Integer> gradeTerms, BigDecimal cap,
        BigDecimal proofThreshold, BigDecimal noteThreshold, SettingHistory history, Permissions permissions, Integer graceDays,
        LocalDate entryDate, Map<String, Integer> gradeGrace, Map<String, BigDecimal> gradeProofThreshold, BigDecimal pot,
        String parent, int fiscalStartMonth, BigDecimal alertThreshold, String rounding) {
}
package net.officefloor.hq.app.setting;

import java.util.Map;

/** Body of a settings save: who is making it and the settings it changes — the clerk limit (blank: no limit) and
 *  the floor and the terms (days) and the late percent and the policy date (yyyy-mm-dd; blank: the sheet's today) and the period numbering from (yyyy-mm-dd; blank: off) and grades' own terms (days by grade;
 *  blank: none, the sheet's terms) and the cap (blank: none) and the proof threshold (blank: none) and the permission matrix (roles by action, comma separated; blank: the standing rule) and the grace days (blank: off) and the note threshold (blank: none) and the entry date (yyyy-mm-dd; blank: off) and grades' grace (days by grade; blank: none) and grades' proof thresholds (amounts by grade; blank: none, the sheet's) and the pot (blank: none) and the parent sheet (a sheet id; blank: none) and the fiscal year start month (1 to 12) and the alert threshold (blank: off) and the rounding mode (half-up or half-even; blank: none); one left out (null) is left as it is;
 *  and, by key (clerk-limit, floor, terms, terms-A/B/C, grace-A/B/C, late-pct, cap, proof-threshold, proof-threshold-A/B/C, note-threshold), the from-date (yyyy-mm-dd) a dated one it sets
 *  is recorded from (left out or blank: the sheet's today). */
public record SettingsRequest(String user, String clerkLimit, String floor, String terms, String latePct,
        String policyDate, String periodNumberingFrom, Map<String, String> gradeTerms, String cap,
        Map<String, String> from, String proofThreshold, Map<String, String> perms, String graceDays, String noteThreshold,
        String entryDate, Map<String, String> gradeGrace, Map<String, String> gradeProofThreshold, String pot, String parent,
        String fiscalStartMonth, String alertThreshold, String rounding) {
}
package net.officefloor.hq.app.setting;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.Map;

/** A validated settings save: who is making it, and the settings it changes, in order — whether it sets the clerk
 *  limit and to what (two decimals; null: no limit), and the floor it sets (two decimals; null: left as it is) and the terms it sets (days; null: left as it is) and the late percent it sets (two decimals; null: left as it is), and whether it sets the policy date and to what (null: blank, the sheet's today), and whether it sets the period numbering from and to what (null: blank, off), and the grades whose own terms it sets
 *  (A, B, C order) and to what (days; null: none, the sheet's terms), and whether it sets the cap and to what (two
 *  decimals; null: none), and the from-dates given for the dated ones it sets, by key (one not given: from the sheet's
 *  today), and whether it sets the proof threshold and to what (two decimals; null: none), and the permission entries it sets
 *  (in action order) and to what (roles comma separated; '': the standing rule), and whether it sets the grace days and to what (days; null: off), and whether it sets the note threshold and to what (two decimals; null: none), and whether it sets the entry date and to what (null: blank, off), and the grades whose grace it sets (A, B, C order) and to what (days; null: none), and the grades whose own proof threshold it sets (A, B, C order) and to what (two decimals; null: none, the sheet's), and whether it sets the pot and to what (two decimals; null: none), and whether it sets the parent sheet and to what (a sheet id; null: none), and the fiscal year start month it sets (1 to 12; null: left as it is), and whether it sets the alert threshold and to what (two decimals; null: off), and whether it sets the rounding mode and to what (half-up or half-even; null: none). */
public record SettingsInput(String user, boolean setsClerkLimit, BigDecimal clerkLimit, BigDecimal floor,
        Integer terms, BigDecimal latePct, boolean setsPolicyDate, LocalDate policyDate,
        boolean setsPeriodNumberingFrom, LocalDate periodNumberingFrom,
        Map<String, Integer> gradeTerms, boolean setsCap, BigDecimal cap,
        Map<String, LocalDate> from, boolean setsProofThreshold, BigDecimal proofThreshold,
        Map<String, String> perms, boolean setsGraceDays, Integer graceDays,
        boolean setsNoteThreshold, BigDecimal noteThreshold,
        boolean setsEntryDate, LocalDate entryDate, Map<String, Integer> gradeGrace,
        Map<String, BigDecimal> gradeProofThreshold, boolean setsPot, BigDecimal pot,
        boolean setsParent, String parent, Integer fiscalStartMonth, boolean setsAlertThreshold, BigDecimal alertThreshold,
        boolean setsRounding, String rounding) {
}
package net.officefloor.hq.app.setting;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/** The settings as the screen shows them: the clerk limit with two decimals ('' when there is none) and the floor
 *  with two decimals and the terms in days and the late percent with two decimals and the policy date (yyyy-mm-dd; '' when blank) and the period numbering from (yyyy-mm-dd; '' when off) and each grade's own
 *  terms in days ('' when it has none: it uses the sheet's terms) and the cap with two decimals ('' when there is none) and the proof threshold with two decimals ('' when there is none), all as in force on the sheet's today; and every value
 *  recorded for each dated setting, by key, oldest from-date first; and the permission matrix, by action ('' when blank); and the grace days ('' when off); and the note threshold with two decimals ('' when there is none), in force on the sheet's today; and the entry date (yyyy-mm-dd; '' when off); and each grade's grace in days ('' when it has none) and each grade's own proof threshold with two decimals ('' when it has none: it uses the sheet's), in force on the sheet's today; and the pot with two decimals ('' when there is none; not dated); and the parent sheet id ('' when there is none; not dated); and the fiscal year start month, 1 to 12 (not dated); and the alert threshold with two decimals ('' when off; not dated); and the rounding mode, half-up or half-even ('' when none), in force on the sheet's today. */
public record SettingsResponse(String clerkLimit, String floor, String terms, String latePct,
        String policyDate, String periodNumberingFrom, Map<String, String> gradeTerms, String cap,
        Map<String, List<Dated>> dated, String proofThreshold, Map<String, String> perms, String graceDays, String noteThreshold,
        String entryDate, Map<String, String> gradeGrace, Map<String, String> gradeProofThreshold, String pot, String parent,
        String fiscalStartMonth, String alertThreshold, String rounding) {

    /** A dated setting's value ('' when blank) and the date (yyyy-mm-dd) it is in force from. */
    public record Dated(String from, String value) {
    }

    public static SettingsResponse from(Settings s) {
        return new SettingsResponse(SettingsResponse.text(s.clerkLimit()), SettingsResponse.text(s.floor()),
                String.valueOf(s.terms()), SettingsResponse.text(s.latePct()),
                s.policyDate() != null ? s.policyDate().toString() : "",
                s.periodNumberingFrom() != null ? s.periodNumberingFrom().toString() : "", gradeTerms(s),
                SettingsResponse.text(s.cap()), dated(s), SettingsResponse.text(s.proofThreshold()),
                s.permissions().entries(), s.graceDays() != null ? String.valueOf(s.graceDays()) : "",
                SettingsResponse.text(s.noteThreshold()), s.entryDate() != null ? s.entryDate().toString() : "",
                byGrade(s.gradeGrace()), amountsByGrade(s.gradeProofThreshold()),
                SettingsResponse.text(s.pot()), s.parent() != null ? s.parent() : "",
                String.valueOf(s.fiscalStartMonth()), SettingsResponse.text(s.alertThreshold()),
                s.rounding() != null ? s.rounding() : "");
    }

    private static Map<String, List<Dated>> dated(Settings s) {
        Map<String, List<Dated>> dated = new LinkedHashMap<>();
        for (String key : SettingHistory.KEYS) {
            List<Dated> values = new ArrayList<>();
            s.history().of(key).forEach((from, value) -> values.add(new Dated(from.toString(), value != null ? value : "")));
            dated.put(key, values);
        }
        return dated;
    }

    private static Map<String, String> gradeTerms(Settings s) {
        return byGrade(s.gradeTerms());
    }

    private static Map<String, String> byGrade(Map<String, Integer> days) {
        Map<String, String> shown = new LinkedHashMap<>();
        for (String grade : ValidateSettings.GRADES) {
            Integer d = days.get(grade);
            shown.put(grade, d != null ? String.valueOf(d) : "");
        }
        return shown;
    }

    private static Map<String, String> amountsByGrade(Map<String, java.math.BigDecimal> amounts) {
        Map<String, String> shown = new LinkedHashMap<>();
        for (String grade : ValidateSettings.GRADES) {
            shown.put(grade, SettingsResponse.text(amounts.get(grade)));
        }
        return shown;
    }

    static String text(java.math.BigDecimal limit) {
        return limit != null ? limit.toPlainString() : "";
    }
}
package net.officefloor.hq.app.setting;

import net.officefloor.hq.app.Audit;
import net.officefloor.plugin.variable.Val;

/** Record each saved setting in the audit file, a line per setting the save sets, with the value saved, and
 *  from=<date> at its end when a from-date was given. */
public class AuditSettingChanged {
    public void audit(@Val SettingsInput input, @Val Settings settings, Audit audit) {
        String head = "SETTING_CHANGED sheet=" + settings.sheetId() + " by=" + input.user() + " key=";
        if (input.setsClerkLimit()) {
            audit.record(head + "clerk-limit value=" + SettingsResponse.text(input.clerkLimit()) + from(input, "clerk-limit"));
        }
        if (input.floor() != null) {
            audit.record(head + "floor value=" + SettingsResponse.text(input.floor()) + from(input, "floor"));
        }
        if (input.terms() != null) {
            audit.record(head + "terms value=" + input.terms() + from(input, "terms"));
        }
        input.gradeTerms().forEach((grade, days) -> audit.record(head + "terms-" + grade + " value="
                + (days != null ? days : "") + from(input, "terms-" + grade)));
        if (input.latePct() != null) {
            audit.record(head + "late-pct value=" + SettingsResponse.text(input.latePct()) + from(input, "late-pct"));
        }
        if (input.setsPolicyDate()) {
            audit.record(head + "policy-date value=" + (input.policyDate() != null ? input.policyDate() : ""));
        }
        if (input.setsPeriodNumberingFrom()) {
            audit.record(head + "period-numbering-from value="
                    + (input.periodNumberingFrom() != null ? input.periodNumberingFrom() : ""));
        }
        if (input.setsCap()) {
            audit.record(head + "cap value=" + SettingsResponse.text(input.cap()) + from(input, "cap"));
        }
        if (input.setsProofThreshold()) {
            audit.record(head + "proof-threshold value=" + SettingsResponse.text(input.proofThreshold())
                    + from(input, "proof-threshold"));
        }
        if (input.setsNoteThreshold()) {
            audit.record(head + "note-threshold value=" + SettingsResponse.text(input.noteThreshold())
                    + from(input, "note-threshold"));
        }
        if (input.setsGraceDays()) {
            audit.record(head + "grace-days value=" + (input.graceDays() != null ? input.graceDays() : ""));
        }
        if (input.setsEntryDate()) {
            audit.record(head + "entry-date value=" + (input.entryDate() != null ? input.entryDate() : ""));
        }
        input.gradeGrace().forEach((grade, days) -> audit.record(head + "grace-" + grade + " value="
                + (days != null ? days : "") + from(input, "grace-" + grade)));
        input.gradeProofThreshold().forEach((grade, amount) -> audit.record(head + "proof-threshold-" + grade + " value="
                + SettingsResponse.text(amount) + from(input, "proof-threshold-" + grade)));
        if (input.setsPot()) {
            audit.record(head + "pot value=" + SettingsResponse.text(input.pot()));
        }
        if (input.setsParent()) {
            audit.record(head + "parent value=" + (input.parent() != null ? input.parent() : ""));
        }
        if (input.fiscalStartMonth() != null) {
            audit.record(head + "fiscal-start-month value=" + input.fiscalStartMonth());
        }
        if (input.setsAlertThreshold()) {
            audit.record(head + "alert-threshold value=" + SettingsResponse.text(input.alertThreshold()));
        }
        if (input.setsRounding()) {
            audit.record(head + "rounding value=" + (input.rounding() != null ? input.rounding() : "")
                    + from(input, SettingHistory.ROUNDING));
        }
        input.perms().forEach((action, roles) -> audit.record(head + "perm-" + action + " value=" + roles));
    }

    private static String from(SettingsInput input, String key) {
        var from = input.from().get(key);
        return from != null ? " from=" + from : "";
    }
}
package net.officefloor.hq.app.setting;

import java.math.BigDecimal;
import java.time.LocalDate;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;

/** Save the settings the input sets: each dated one recorded from its from-date (not given: the sheet's today),
 *  keeping the values already recorded (one from that same date is replaced); the policy date and the period
 *  numbering from and the grace days and the pot and the parent sheet and the fiscal year start month and the alert threshold and the permission matrix as
 *  they are. */
public class SaveSettings {
    public void save(@PathVariable("sheetId") String sheetId, @Val SettingsInput input, SettingRepository repository,
            Out<Settings> settings) {
        String id = sheetId.trim();
        LocalDate today = repository.today(id);
        if (input.setsClerkLimit()) {
            repository.setDated(id, "clerk-limit", text(input.clerkLimit()), from(input, "clerk-limit", today));
        }
        if (input.floor() != null) {
            repository.setDated(id, "floor", text(input.floor()), from(input, "floor", today));
        }
        if (input.terms() != null) {
            repository.setDated(id, "terms", String.valueOf(input.terms()), from(input, "terms", today));
        }
        input.gradeTerms().forEach((grade, days) -> repository.setDated(id, "terms-" + grade,
                days != null ? String.valueOf(days) : null, from(input, "terms-" + grade, today)));
        input.gradeGrace().forEach((grade, days) -> repository.setDated(id, "grace-" + grade,
                days != null ? String.valueOf(days) : null, from(input, "grace-" + grade, today)));
        input.gradeProofThreshold().forEach((grade, amount) -> repository.setDated(id, "proof-threshold-" + grade,
                text(amount), from(input, "proof-threshold-" + grade, today)));
        if (input.latePct() != null) {
            repository.setDated(id, "late-pct", text(input.latePct()), from(input, "late-pct", today));
        }
        if (input.setsPolicyDate()) {
            repository.setPolicyDate(id, input.policyDate());
        }
        if (input.setsPeriodNumberingFrom()) {
            repository.setPeriodNumberingFrom(id, input.periodNumberingFrom());
        }
        if (input.setsCap()) {
            repository.setDated(id, "cap", text(input.cap()), from(input, "cap", today));
        }
        if (input.setsProofThreshold()) {
            repository.setDated(id, "proof-threshold", text(input.proofThreshold()), from(input, "proof-threshold", today));
